/**
 * Prompt templates, in code.
 *
 * The brief structure fm2 refined (worktree isolation assertion, status
 * protocol, definition of done) is generated by the spawn tool rather than
 * hand-scaffolded per task. fm2's own evidence for why templates belong in code:
 * a hand-written wait-for-another-lane clause cost 3.5 lane-days, and every lane
 * briefed from that text self-blocked identically. The scaffold is the contract.
 *
 * The captain's audit of a real fm2 brief removed four things, and none of them
 * appear here: the Herdr safety-gate section, every no-mistakes mention, the
 * project-memory boilerplate, and the delivery-mode taxonomy.
 *
 * Roles: ORCHESTRATOR (captain-facing, one per fleet) and WORKER (one per task).
 * Names are plain so a status line or prompt can never be ambiguous about which
 * is meant.
 */
import * as path from "node:path";
import { dataDir } from "./home";

/**
 * Projects whose convention is to sign agent-authored comments.
 *
 * Captain's decision: the signature is lindy's convention, not a global rule, so
 * it rides per-project rather than in every brief. The CONDUCT rule above it —
 * answer facts, never argue — is global, because that one is about behavior and
 * applies wherever an agent posts.
 */
/**
 * Projects whose convention is to sign agent-authored comments.
 *
 * Signing is one team's convention, not a universal rule, so it rides per project
 * instead of appearing in every brief. The CONDUCT rule next to it — answer with
 * facts, never argue with a reviewer — is global, because that one is about
 * behavior and applies wherever an agent posts.
 *
 * Set DECK_SIGNATURE_PROJECTS to a comma-separated list to change this.
 */
function signatureProjects(): Set<string> {
	const configured = process.env.DECK_SIGNATURE_PROJECTS;
	if (configured === undefined) return new Set(["lindy"]);
	return new Set(
		configured
			.split(",")
			.map((name) => name.trim())
			.filter((name) => name.length > 0),
	);
}

/**
 * Frozen copy of the 3 load-bearing traps from data/lindy-domain.md.
 *
 * Inlined verbatim on purpose: a path alone decays (workers skip the read), and
 * reading the live file at brief time would make the brief depend on home-file
 * state. Keep this in sync with lindy-domain.md when the traps change.
 */
const LINDY_TRAPS = `1. **Graphite lands-and-closes**: a queue-merged PR reads \`state=closed, merged=false\`. Before any "not landed" verdict, search main for the squash commit \`(#N)\`.
2. **Migration gate**: a diff touching migrations/ or packages/database-migrations/ makes the migration run (stg → verify → prod → verify, with evidence) mandatory before landing is done. Unapplied migrations block ALL of CI repo-wide.
3. **Review requests silently no-op**: after requesting reviewers (or any GH edit), verify via the requested_reviewers API. Plausible-but-wrong logins return ok.`;

/**
 * Standing doctrine for a worker brief: absolute paths into the knowledge pack
 * plus the frozen traps. Progressive disclosure — paths and one-liners only,
 * never the full pack contents. Exported so smithers seats can share the same
 * doctrine string.
 */
export function buildStandingDoctrine(project?: string): string {
	const data = dataDir();
	const distill = path.join(data, "ref", "distill");
	if (project?.toLowerCase() === "lindy") {
		return `## Standing doctrine (lindy)

Read before you touch prod, a PR, or Linear. Full doctrine (absolute paths):

- ${path.join(data, "KNOWLEDGE.md")} (load index)
- ${path.join(data, "lindy-domain.md")} · ${path.join(data, "lindy-ops.md")} · ${path.join(data, "lindy-pipeline.md")} · ${path.join(data, "lindy-standing-work.md")} · ${path.join(data, "lindy-learnings.md")}
- ${path.join(distill, "STANDING-RULES.md")} · ${path.join(distill, "SETUP-CHECKLIST.md")} · ${path.join(distill, "CREDS-AND-TOOLS.md")}

The 3 load-bearing traps (verbatim, non-negotiable):

${LINDY_TRAPS}

And:

- Prod DB reads: \`pnpm repl:prod-readonly\` only. Repo skills live under \`.agent/skills/\`.
- Sitevars: query the collection sorted \`version: -1\` — never \`getSitevar()\` (REPL cache returns registry defaults) and never unsorted \`findOne\`.
- Merges: yolo OFF. Per-PR captain stamp + merge word, always. Never run a no-mistakes pipeline.
- Reviewers: CODEOWNERS + review-frequency + gh-reviewer-lookup skill. Never Ali as code reviewer.
- CI/review watching belongs to the orchestrator's wake engine — never sleep-poll in your own run; workers that poll-and-exit read as dead.`;
	}
	return `## Standing doctrine

Distilled fleet rules (absolute paths, open when the topic goes deep):

- ${path.join(distill, "STANDING-RULES.md")}
- ${path.join(data, "captain.md")} (captain's preferences)
- ${path.join(data, "secrets-map.md")} (credential locations, names only — never values)

You never contact the captain directly; every question routes through your status file.`;
}

export type WorkerBriefInput = {
	taskId: string;
	/** What to do. Front-loaded and self-contained: this is the whole contract. */
	task: string;
	/** Acceptance criteria. A worker is done when these pass, not when it feels done. */
	acceptance: string[];
	worktree: string;
	statusFile: string;
	kind: "ship" | "scout";
	project?: string;
	branch?: string;
	/** Scout only: where the report must land. */
	reportPath?: string;
	/** Extra task-specific context. Never lifecycle boilerplate. */
	context?: string;
};

/**
 * Worker bootstrap. Kept short on purpose: fm2's evidence is that 5.6-7K-char
 * front-loaded briefs needed 0-1 steers while iterative ones needed dozens, and
 * that prose rules decay. Long-form doctrine lives in skills, not here.
 */
export function workerBrief(input: WorkerBriefInput): string {
	const {
		taskId,
		task,
		acceptance,
		worktree,
		statusFile,
		kind,
		branch,
		reportPath,
		context,
		project,
	} = input;

	const sections: string[] = [];

	sections.push(`# Task: ${taskId}

${task}`);

	if (context !== undefined && context.trim().length > 0) {
		sections.push(`## Context\n\n${context.trim()}`);
	}

	sections.push(`## Acceptance

You are done when all of these are true, and not before:

${acceptance.map((item) => `- ${item}`).join("\n")}`);

	// Isolation assertion. Non-negotiable: a worker that writes to the primary
	// checkout corrupts the captain's own working copy.
	sections.push(`## Isolation

You are in a disposable worktree: ${worktree}

Verify before you write anything: run \`pwd -P\` and \`git rev-parse --show-toplevel\`.
Both must resolve inside that path. The path check is authoritative.
If it does not match, stop and append \`blocked: launched outside the task worktree\`
to your status file. Do not branch, commit, or edit.${
		branch === undefined ? "" : `\n\nFirst action: \`git checkout -b ${branch}\``
	}`);

	sections.push(`## Reporting

Report one event at a time with:

\`\`\`
deck-v2 note ${taskId} {verb} "{one short line}" --epoch "$DECK_RUN_EPOCH"
\`\`\`

Verbs: working, needs-decision, blocked, paused, resolved, done, failed.

Use that command, not a raw append to the file. It carries your run epoch, so if
this task was cancelled and restarted, your late report is refused instead of
being mistaken for the live run's. It also rejects a malformed line before it
reaches the orchestrator. If the command refuses your append, you have been
superseded: stop, and change nothing further.

**Your LAST action, always, is a terminal report.** Run the command with \`done:\` or
\`failed:\` before you stop, and run it even if you have already summarized in your
output. Nothing reads your output — the orchestrator only sees this file, so a
finished task that never reports is a task nobody knows is finished, and it gets
chased as stuck.

Between the start and that final line, report sparingly: only a phase change the
orchestrator can act on. Progress narration belongs in your output, not this file —
a \`working:\` line that says nothing actionable costs a supervision turn.

Use \`blocked:\` when you are stuck and need help. Use \`paused:\` only when you are
deliberately waiting on a known external event that will clear on its own.
If you hit the same obstacle twice, append \`blocked:\` and stop.

You never contact the captain. If a choice belongs to him (product direction,
irreversible action, scope change), append \`needs-decision: {the options}\` and
stop. The orchestrator asks him and returns the answer to you. Do not look for a
way to ask him yourself: one channel means one place to look, and two channels
lose decisions between them.`);

	sections.push(`## Scope

Do what the task says and stop. No adjacent fixes, no refactors, no cleanup you
were not asked for. A smaller diff is a better diff.

Never weigh "developer time" or estimate effort as a tradeoff. Correctness,
completeness and conciseness decide. Code is cheap; redoing it is not.

Before you hand-solve an operational flow — auth, deploy, CI, debugging
production — check this repo's committed skills and docs first. Most repos
document their own rails, and the rails are faster and correct.

When a credential seems dead, suspect your own extraction before the credential.
Values in \`.env\` files are often quoted, so \`source\` works while \`grep\`/\`cut\`
extraction silently yields the quotes too and the request returns 401. A wrong
"the key is dead" verdict sends the captain to rotate a key that was fine.

Write as little code as the task allows. Prefer what already exists in this
repo, then the standard library, then a native platform feature, then an
already-installed dependency. Do not add a dependency for something a few lines
can do. Do not add an abstraction with one caller.

Tests: ask what assertion would actually catch this breaking, and write that.
Do not write one test per changed line. A test earns its place by going red on
the old behavior — if it passes against the code before your change, it is
testing nothing. Verify the mechanism fires rather than trusting a green run.`);

	sections.push(buildStandingDoctrine(project));

	if (kind === "scout") {
		sections.push(`## Definition of done

This is a scout task: the deliverable is the report, not a PR. Do not open one.

Write your findings to ${reportPath ?? "the report path in your task record"}.
The report must stand alone: what you did, what you found, the evidence
(commands run, output, file:line references), and what you recommend.

Your worktree is scratch and is discarded afterwards, so anything worth keeping
must be in the report. When it is complete, append \`done: {one-line conclusion}\`.`);
	} else {
		sections.push(`## Definition of done

Implement, commit on your branch, and open a PR.

Commit and PR titles use one of two forms:
  \`[TICKET-123]: short description\`
  \`type(area): short description\`   — type is fix, feat, chore, refactor, perf, ci, docs

Example: \`fix(evals): retry whole eval 5x on fallback + fallback visibility\`

The PR description is short: what broke, why it broke, what the fix does. For a
UI change, attach screenshots to the PR by uploading them — never commit image
files to the repo.

Code comments explain what a reader needs to understand the code. Never write a
comment that references a ticket as its reason: "FIXES ABC-123" in a comment is
noise, because the ticket is in the commit and the PR.

Never add a co-author or agent-attribution line to a commit.

Then append \`done: PR {url}\` and stop. You never merge; the captain gives that
word.

If you watch your own PR afterwards: review fixes are plain commits on this same
branch. Never open a second PR or a stacked child PR for rework on this task.

A PR that landed through a merge queue can read as closed and not merged.
Landing truth is the squash commit \`(#N)\` on the base branch, never the merged
flag.

In PR threads: agree, or answer with facts. Never argue with a reviewer — if you
believe a reviewer is wrong, append \`needs-decision:\` and stop. Write comments in
Simplified Technical English.${signatureProjects().has(project ?? "") ? `

Sign every comment you post \`-- tim's agent\`, because a reader deserves to know a
person did not write it.` : ""}

If review or CI comes back: a scoped correctness fix (a failing assertion, a
lint error, a rebase) is yours to make immediately. A product or architecture
question is not — append \`needs-decision:\` with the options and stop.`);
	}

	return sections.join("\n\n");
}
